INSERT INTO products (id, sku, name, slug, category, description, price, cost_price, stock, image_url, supplier_contact, internal_notes) VALUES
(1, 'PROD-001', 'Logitech Headset Wireless 7.1 Strix G16', 'logitech-headset-wireless-7-1-strix-g16', 'Audio', 'O produto Logitech Headset Wireless 7.1 Strix G16 oferece uma experiencia superior. Auriculares de alta fidelidade sonora com cancelamento ativo de ruido (ANC), diafragmas de 50mm de neodimio e autonomia ate 40 horas continuas.', 318.50, 181.99, 66, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', 'sales@keyswitch.io', 'Stock armazenado no corredor B-2.'),
(2, 'PROD-002', 'Corsair Rato Otico Ergonomico ProArt Studio', 'corsair-rato-otico-ergonomico-proart-studio', 'Perifericos', 'O produto Corsair Rato Otico Ergonomico ProArt Studio oferece uma experiencia superior. Rato gamer com sensor otico de precisao extrema ate 26.000 DPI, aceleracao de 50G, patins em PTFE puro 100% e 8 botoes totalmente programaveis.', 139.73, 68.40, 68, 'https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=600&auto=format&fit=crop&q=80', 'contact@displaytech.cn', 'Produto de elevada rotacao de vendas.'),
(3, 'PROD-003', 'Razer Monitor 4K IPS HDR600 Legion Pro 5', 'razer-monitor-4k-ips-hdr600-legion-pro-5', 'Monitores', 'O produto Razer Monitor 4K IPS HDR600 Legion Pro 5 oferece uma experiencia superior. Monitor profissional para edicao de imagem com calibracao de fabrica Delta E < 2, HDR600, hub USB-C integrado com Power Delivery ate 90W.', 651.14, 328.60, 107, 'https://images.unsplash.com/photo-1551645120-d70bfe84c826?w=600&auto=format&fit=crop&q=80', 'logistics@furnitech.pt', 'Garantia de fabricante de 3 anos incluida.'),
(4, 'PROD-004', 'Asus ROG Cadeira de Escritorio Mesh Pro Blade 15', 'asus-rog-cadeira-de-escritorio-mesh-pro-blade-15', 'Mobiliario', 'O produto Asus ROG Cadeira de Escritorio Mesh Pro Blade 15 oferece uma experiencia superior. Cadeira de escritorio de alta gama com suporte lombar dinamico, malha respiravel de alta resistencia, encosto de cabeca ajustavel e base em aluminio.', 362.25, 163.17, 109, 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=600&auto=format&fit=crop&q=80', 'sales@camvision.org', 'Embalagem reforcada necessaria para transporte.'),
(5, 'PROD-005', 'Samsung Webcam 4K HDR Pro PRO X 2', 'samsung-webcam-4k-hdr-pro-pro-x-2', 'Video', 'O produto Samsung Webcam 4K HDR Pro PRO X 2 oferece uma experiencia superior. Webcam topo de gama com sensor Sony STARVIS 4K a 60fps, focagem automatica por IA, enquadramento automatico e duplo microfone estereo com cancelamento de ruido.', 234.22, 151.99, 88, 'https://images.unsplash.com/photo-1585060544812-6b45742d762f?w=600&auto=format&fit=crop&q=80', 'component_world@hardware.de', 'Lote 5 verificado no controlo de qualidade.'),
(6, 'PROD-006', 'Sony Processador CPU 16-Core K70 RGB PRO', 'sony-processador-cpu-16-core-k70-rgb-pro', 'Componentes', 'O produto Sony Processador CPU 16-Core K70 RGB PRO oferece uma experiencia superior. Processador de arquitetura avancada de 16 nucleos e 24 threads com velocidade boost ate 5.7GHz, 80MB de cache combinada e suporte PCIe 5.0.', 2173.92, 1264.07, 87, 'https://images.unsplash.com/photo-1562976540-1502c2145186?w=600&auto=format&fit=crop&q=80', 'storage_solutions@data.com', 'Stock armazenado no corredor A-7.'),
(7, 'PROD-007', 'Dell Alienware SSD Portatil USB 3.2 1TB UltraGear 27GP', 'dell-alienware-ssd-portatil-usb-3-2-1tb-ultragear-27gp', 'Armazenamento', 'O produto Dell Alienware SSD Portatil USB 3.2 1TB UltraGear 27GP oferece uma experiencia superior. SSD externo ultra-compacto com corpo em borracha resistente a quedas ate 2 metros, protecao IP55 contra agua e poeiras e velocidades USB 3.2 Gen 2.', 415.27, 236.65, 55, 'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?w=600&auto=format&fit=crop&q=80', 'network_pro@cables.pt', 'Produto de elevada rotacao de vendas.'),
(8, 'PROD-008', 'HyperX Adaptador USB Wi-Fi 6 Dual Band ZOWIE XL2546K', 'hyperx-adaptador-usb-wi-fi-6-dual-band-zowie-xl2546k', 'Redes', 'O produto HyperX Adaptador USB Wi-Fi 6 Dual Band ZOWIE XL2546K oferece uma experiencia superior. Placa de rede USB com antenas direcionais orientaveis de alto ganho para ligacao Wi-Fi rapida e estavel em computadores de secretaria ou portateis.', 431.40, 251.59, 89, 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=600&auto=format&fit=crop&q=80', 'laptops_direct@devices.com', 'Garantia de fabricante de 3 anos incluida.'),
(9, 'PROD-009', 'MSI Portatil Gamer 16 QHD 240Hz TITAN Evo 2026', 'msi-portatil-gamer-16-qhd-240hz-titan-evo-2026', 'Laptops', 'O produto MSI Portatil Gamer 16 QHD 240Hz TITAN Evo 2026 oferece uma experiencia superior. Computador portatil gaming com ecra QHD+ de 16 polegadas a 240Hz, processador Intel Core i9 de 13a geracao, placa grafica RTX 4070, 32GB RAM e SSD de 1TB.', 517.61, 294.89, 107, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=600&auto=format&fit=crop&q=80', 'audio_tech@supplier.com', 'Embalagem reforcada necessaria para transporte.'),
(10, 'PROD-010', 'Gigabyte AORUS Powerbank Fast Charge 20000mAh Facecam Pro', 'gigabyte-aorus-powerbank-fast-charge-20000mah-facecam-pro', 'Gadgets', 'O produto Gigabyte AORUS Powerbank Fast Charge 20000mAh Facecam Pro oferece uma experiencia superior. Bateria externa de elevada capacidade de 20.000 mAh com portas USB-C Power Delivery de 65W, capaz de carregar rapidamente um portatil, tablet ou smartphone.', 166.51, 83.02, 104, 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=600&auto=format&fit=crop&q=80', 'sales@keyswitch.io', 'Lote 10 verificado no controlo de qualidade.'),
(11, 'PROD-011', 'Lenovo Legion Placa de Som Externa DAC Beast RGB', 'lenovo-legion-placa-de-som-externa-dac-beast-rgb', 'Audio', 'O produto Lenovo Legion Placa de Som Externa DAC Beast RGB oferece uma experiencia superior. Auriculares de alta fidelidade sonora com cancelamento ativo de ruido (ANC), diafragmas de 50mm de neodimio e autonomia ate 40 horas continuas.', 429.50, 220.90, 46, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=600&auto=format&fit=crop&q=80', 'contact@displaytech.cn', 'Stock armazenado no corredor F-12.'),
(12, 'PROD-012', 'Audio-Technica Mesa Digitalizadora MX Master 3S', 'audio-technica-mesa-digitalizadora-mx-master-3s', 'Perifericos', 'O produto Audio-Technica Mesa Digitalizadora MX Master 3S oferece uma experiencia superior. Rato gamer com sensor otico de precisao extrema ate 26.000 DPI, aceleracao de 50G, patins em PTFE puro 100% e 8 botoes totalmente programaveis.', 158.76, 96.44, 90, 'https://images.unsplash.com/photo-1595225476474-87563907a212?w=600&auto=format&fit=crop&q=80', 'logistics@furnitech.pt', 'Produto de elevada rotacao de vendas.'),
(13, 'PROD-013', 'Sennheiser Monitor 4K IPS HDR600 BlackWidow V4', 'sennheiser-monitor-4k-ips-hdr600-blackwidow-v4', 'Monitores', 'O produto Sennheiser Monitor 4K IPS HDR600 BlackWidow V4 oferece uma experiencia superior. Monitor profissional para edicao de imagem com calibracao de fabrica Delta E < 2, HDR600, hub USB-C integrado com Power Delivery ate 90W.', 1190.80, 675.46, 20, 'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?w=600&auto=format&fit=crop&q=80', 'sales@camvision.org', 'Garantia de fabricante de 3 anos incluida.'),
(14, 'PROD-014', 'LG UltraGear Secretaria Motorizada Standing Desk Cloud III Wireless', 'lg-ultragear-secretaria-motorizada-standing-desk-cloud-iii-wireless', 'Mobiliario', 'O produto LG UltraGear Secretaria Motorizada Standing Desk Cloud III Wireless oferece uma experiencia superior. Secretaria de escritorio eletrica com motor duplo silencioso, ajuste de altura entre 65cm e 130cm, painel digital com posicoes de memoria e gestao de cabos.', 264.39, 160.65, 93, 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?w=600&auto=format&fit=crop&q=80', 'component_world@hardware.de', 'Embalagem reforcada necessaria para transporte.'),
(15, 'PROD-015', 'BenQ ZOWIE Anel de Iluminacao Ring Light LED OptiPlex Ultra', 'benq-zowie-anel-de-iluminacao-ring-light-led-optiplex-ultra', 'Video', 'O produto BenQ ZOWIE Anel de Iluminacao Ring Light LED OptiPlex Ultra oferece uma experiencia superior. Painel de iluminacao LED para estudio com temperatura de cor ajustavel de 2900K a 7000K, brilho regulavel ate 2500 lumens e controlo por app movel ou PC.', 400.66, 208.54, 13, 'https://images.unsplash.com/photo-1585060544812-6b45742d762f?w=600&auto=format&fit=crop&q=80', 'storage_solutions@data.com', 'Lote 15 verificado no controlo de qualidade.'),
(16, 'PROD-016', 'Secretlab Processador CPU 16-Core OLED Swift', 'secretlab-processador-cpu-16-core-oled-swift', 'Componentes', 'O produto Secretlab Processador CPU 16-Core OLED Swift oferece uma experiencia superior. Processador de arquitetura avancada de 16 nucleos e 24 threads com velocidade boost ate 5.7GHz, 80MB de cache combinada e suporte PCIe 5.0.', 519.96, 242.44, 88, 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?w=600&auto=format&fit=crop&q=80', 'network_pro@cables.pt', 'Stock armazenado no corredor E-17.'),
(17, 'PROD-017', 'Elgato SSD NVMe M.2 2TB PCIe 4.0 Odyssey Neo G9', 'elgato-ssd-nvme-m-2-2tb-pcie-4-0-odyssey-neo-g9', 'Armazenamento', 'O produto Elgato SSD NVMe M.2 2TB PCIe 4.0 Odyssey Neo G9 oferece uma experiencia superior. Unidade de estado solido NVMe M.2 PCIe Gen4 x4 com velocidades sequenciais de leitura ate 7300 MB/s e escrita ate 6600 MB/s, dissipador termico em aluminio incluido.', 267.38, 168.49, 41, 'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?w=600&auto=format&fit=crop&q=80', 'laptops_direct@devices.com', 'Produto de elevada rotacao de vendas.'),
(18, 'PROD-018', 'Kingston Fury Switch Gerido 24 Portas Gigabit BarraCuda Pro', 'kingston-fury-switch-gerido-24-portas-gigabit-barracuda-pro', 'Redes', 'O produto Kingston Fury Switch Gerido 24 Portas Gigabit BarraCuda Pro oferece uma experiencia superior. Switch gerivel de montagem em bastidor com 24 portas RJ45 Gigabit, 4 ranhuras SFP+ de 10Gbps, suporte para VLAN, QoS avancado e gestao por interface web.', 115.03, 72.05, 21, 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=600&auto=format&fit=crop&q=80', 'audio_tech@supplier.com', 'Garantia de fabricante de 3 anos incluida.'),
(19, 'PROD-019', 'Crucial Portatil Workstation Ryzen 9 Evo 990 PRO', 'crucial-portatil-workstation-ryzen-9-evo-990-pro', 'Laptops', 'O produto Crucial Portatil Workstation Ryzen 9 Evo 990 PRO oferece uma experiencia superior. Workstation movel de elevado desempenho equipada com processador AMD Ryzen 9, 64GB de memoria DDR5, placa grafica profissional e ecra 4K Adobe RGB 100%.', 2036.41, 1056.25, 47, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=600&auto=format&fit=crop&q=80', 'sales@keyswitch.io', 'Embalagem reforcada necessaria para transporte.'),
(20, 'PROD-020', 'Netgear Nighthawk Carregador Magnetico Wireless 3-em-1 Nighthawk RAXE500', 'netgear-nighthawk-carregador-magnetico-wireless-3-em-1-nighthawk-raxe500', 'Gadgets', 'O produto Netgear Nighthawk Carregador Magnetico Wireless 3-em-1 Nighthawk RAXE500 oferece uma experiencia superior. Base de carregamento sem fios 3-em-1 para carregar simultaneamente smartphone, relogio e auriculares com alinhamento magnetico automatico e LED indicador de carga.', 68.53, 42.55, 17, 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=600&auto=format&fit=crop&q=80', 'contact@displaytech.cn', 'Lote 20 verificado no controlo de qualidade.'),
